class Solution {
public:
    int minimumFinishTime(vector<vector<int>>& tires, int changeTime, int numLaps) {
        vector<long long> minTire(18, 1e18);
        for (auto& t : tires) {
            long long f = t[0], r = t[1];
            long long cur = f, total = f;
            for (int lap = 1; lap <= 17 && cur < changeTime + f; lap++) {
                minTire[lap] = min(minTire[lap], total);
                cur *= r;
                total += cur;
            }
        }
        vector<long long> dp(numLaps + 1, 1e18);
        dp[0] = -changeTime;
        for (int i = 1; i <= numLaps; i++) {
            for (int j = 1; j <= min(i, 17); j++) {
                dp[i] = min(dp[i], dp[i - j] + changeTime + minTire[j]);
            }
        }
        return dp[numLaps];
    }
};

class Solution {
    public int minimumFinishTime(int[][] tires, int changeTime, int numLaps) {
        long[] minTire = new long[18];
        Arrays.fill(minTire, Long.MAX_VALUE / 2);
        for (int[] t : tires) {
            long f = t[0], r = t[1];
            long cur = f, total = f;
            for (int lap = 1; lap <= 17 && cur < changeTime + f; lap++) {
                minTire[lap] = Math.min(minTire[lap], total);
                cur *= r;
                total += cur;
            }
        }
        long[] dp = new long[numLaps + 1];
        Arrays.fill(dp, Long.MAX_VALUE / 2);
        dp[0] = -changeTime;
        for (int i = 1; i <= numLaps; i++) {
            for (int j = 1; j <= Math.min(i, 17); j++) {
                dp[i] = Math.min(dp[i], dp[i - j] + changeTime + minTire[j]);
            }
        }
        return (int) dp[numLaps];
    }
}

var minimumFinishTime = function(tires, changeTime, numLaps) {
    const minTire = new Array(18).fill(Infinity);
    for (const [f, r] of tires) {
        let cur = f, total = f;
        for (let lap = 1; lap <= 17 && cur < changeTime + f; lap++) {
            if (total < minTire[lap]) minTire[lap] = total;
            cur *= r;
            total += cur;
        }
    }
    const dp = new Array(numLaps + 1).fill(Infinity);
    dp[0] = -changeTime;
    for (let i = 1; i <= numLaps; i++) {
        const limit = Math.min(i, 17);
        for (let j = 1; j <= limit; j++) {
            const cand = dp[i - j] + changeTime + minTire[j];
            if (cand < dp[i]) dp[i] = cand;
        }
    }
    return dp[numLaps];
};
